function material(color,options={}){return new THREE.MeshStandardMaterial({color,roughness:.38,metalness:.02,...options});}
function printedMaterial(options={}){return new THREE.MeshBasicMaterial({color:0xffffff,toneMapped:false,...options});}
function textureFromCanvas(width,height,draw){const canvas=document.createElement('canvas');canvas.width=width;canvas.height=height;const c=canvas.getContext('2d');draw(c,width,height);const texture=new THREE.CanvasTexture(canvas);texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());return texture;}
function titleTexture(game,format){const ratio=format.caseMm[1]/format.caseMm[0],w=640,h=Math.max(480,Math.round(w*ratio));return textureFromCanvas(w,h,(c,width,height)=>{const g=c.createLinearGradient(0,0,width,height);g.addColorStop(0,'#182538');g.addColorStop(1,'#07111e');c.fillStyle=g;c.fillRect(0,0,width,height);c.fillStyle=`#${format.accent.toString(16).padStart(6,'0')}`;for(let x=-height;x<width+height;x+=90){c.save();c.translate(x,height*.5);c.rotate(-.62);c.globalAlpha=.3;c.fillRect(-20,-height,40,height*2);c.restore();}c.globalAlpha=1;c.fillStyle='#ffc448';c.fillRect(0,0,width,Math.max(24,height*.045));c.fillStyle='#eaf0f7';c.font=`700 ${Math.round(height*.045)}px Segoe UI, sans-serif`;c.fillText(game.platform.toUpperCase(),width*.07,height*.14);const words=game.title.toUpperCase().split(/\s+/);let line='',lines=[];for(const word of words){const next=`${line} ${word}`.trim();c.font=`800 ${Math.round(height*.1)}px Segoe UI, sans-serif`;if(c.measureText(next).width>width*.84&&line){lines.push(line);line=word;}else line=next;}if(line)lines.push(line);c.fillStyle='#fff';c.textAlign='center';lines.slice(0,3).forEach((text,index)=>c.fillText(text,width*.5,height*(.44+index*.11)));c.font=`700 ${Math.round(height*.038)}px Segoe UI, sans-serif`;c.fillStyle='#bdc8d7';c.fillText(game.id||'LOCAL LIBRARY',width*.5,height*.87);c.textAlign='left';});}
function assetFor(game,kind){return game.artwork?.resolved?.[kind]||(kind==='frontCover'&&game.artKind!=='menu icon'?{url:game.coverUrl,source:'emulator'}:{url:null,source:'generated'});}
function getArtworkTexture(asset,fallback,apply){if(!asset?.url){apply(fallback());return;}const key=asset.url+JSON.stringify(asset.labelRect||null);if(textureCache.has(key)){apply(textureCache.get(key));return;}loader.load(asset.url,texture=>{texture.colorSpace=THREE.SRGBColorSpace;texture.anisotropy=Math.min(8,renderer.capabilities.getMaxAnisotropy());if(asset.labelRect){const[x,y,w,h]=asset.labelRect;texture.repeat.set(w/texture.image.width,h/texture.image.height);texture.offset.set(x/texture.image.width,1-(y+h)/texture.image.height);}textureCache.set(key,texture);apply(texture);},undefined,()=>apply(fallback()));}
function getCoverTexture(game,format,apply){getArtworkTexture(assetFor(game,'frontCover'),()=>titleTexture(game,format),apply);}
function spineTexture(game,format){return textureFromCanvas(128,1024,(c,w,h)=>{c.fillStyle=`#${format.accent.toString(16).padStart(6,'0')}`;c.fillRect(0,0,w,h);c.save();c.translate(w*.62,h*.94);c.rotate(-Math.PI/2);c.fillStyle='#fff';c.font='800 56px Segoe UI, sans-serif';c.fillText(game.title.toUpperCase(),0,0);c.restore();});}
function decorate(root){root.traverse(object=>{if(object.isMesh){object.castShadow=true;object.receiveShadow=true;}});return root;}
function makeCase(game){const format=formats[game.platform],[w,h,d]=format.caseMm.map(value=>value*MM),root=new THREE.Group(),shellMaterial=format.clear?material(format.shell,{transparent:true,opacity:.3,depthWrite:false,roughness:.2}):material(format.shell,{transparent:format.transparent===true,opacity:format.transparent ? .9 : 1,roughness:.34});if(format.clear){const tray=new THREE.Mesh(new RoundedBoxGeometry(w*.965,h*.93,d*.55,3,.018),material(0x171d26,{roughness:.48}));tray.position.z=-d*.13;root.add(tray);}const shell=new THREE.Mesh(new RoundedBoxGeometry(w,h,d,5,Math.min(.035,d*.28)),shellMaterial);root.add(shell);const coverMaterial=printedMaterial();const cover=new THREE.Mesh(new THREE.PlaneGeometry(w*.91,h*.9),coverMaterial);cover.position.z=d/2+.006;root.add(cover);getCoverTexture(game,format,texture=>{coverMaterial.map=texture;coverMaterial.needsUpdate=true;});const spine=new THREE.Mesh(new THREE.PlaneGeometry(d*.82,h*.88),printedMaterial({map:spineTexture(game,format)}));spine.rotation.y=-Math.PI/2;spine.position.x=-w/2-.006;root.add(spine);const band=new THREE.Mesh(new THREE.BoxGeometry(w*.96,Math.max(.025,h*.035),d*1.03),material(format.accent,{roughness:.3}));band.position.y=h*.455;root.add(band);root.position.y=h/2;root.userData.game=game;root.userData.homeZ=0;for(const mesh of [shell,cover,spine,band]){mesh.userData.caseRoot=root;pickables.push(mesh);}return decorate(root);}
function discTexture(game,format){return textureFromCanvas(768,768,(c,w,h)=>{const center=w/2,g=c.createRadialGradient(center,center,w*.05,center,center,w*.5);g.addColorStop(0,'#181d25');g.addColorStop(.1,'#e2e7ed');g.addColorStop(1,'#8290a1');c.fillStyle=g;c.fillRect(0,0,w,h);c.strokeStyle=`#${format.accent.toString(16).padStart(6,'0')}`;c.lineWidth=w*.11;c.beginPath();c.arc(center,center,w*.34,-2.5,.35);c.stroke();c.fillStyle='#111824';c.textAlign='center';c.font='800 39px Segoe UI, sans-serif';c.fillText(game.title.toUpperCase().slice(0,24),center,h*.3);c.font='700 28px Segoe UI, sans-serif';c.fillText(game.id||format.mediumName.toUpperCase(),center,h*.72);});}
function makeDisc(game,format){const diameter=format.mediumMm[0]*MM,thickness=format.mediumMm[1]*MM,shape=new THREE.Shape();shape.absarc(0,0,diameter/2,0,Math.PI*2,false);const hole=new THREE.Path();hole.absarc(0,0,diameter*.075,0,Math.PI*2,true);shape.holes.push(hole);const geometry=new THREE.ExtrudeGeometry(shape,{depth:thickness,bevelEnabled:false,curveSegments:96});geometry.translate(0,0,-thickness/2);const positions=geometry.attributes.position,uvs=geometry.attributes.uv,normals=geometry.attributes.normal;for(let index=0;index<positions.count;index++)if(Math.abs(normals.getZ(index))>.9)uvs.setXY(index,positions.getX(index)/diameter+.5,positions.getY(index)/diameter+.5);uvs.needsUpdate=true;const face=printedMaterial();getArtworkTexture(assetFor(game,'discLabel'),()=>discTexture(game,format),texture=>{face.map=texture;face.needsUpdate=true;});const mesh=new THREE.Mesh(geometry,[face,material(0x778493,{metalness:.75,roughness:.18})]);mesh.position.y=diameter/2;return decorate(mesh);}
function makeCartridge(game){const format=formats.ds,[w,h,d]=format.mediumMm.map(value=>value*MM),shape=new THREE.Shape();shape.moveTo(-w/2,-h/2);shape.lineTo(w/2,-h/2);shape.lineTo(w/2,h*.32);shape.lineTo(w*.36,h/2);shape.lineTo(-w*.32,h/2);shape.lineTo(-w/2,h*.36);shape.closePath();const geometry=new THREE.ExtrudeGeometry(shape,{depth:d,bevelEnabled:true,bevelSize:.008,bevelThickness:.006,bevelSegments:2});geometry.translate(0,0,-d/2);const group=new THREE.Group(),body=new THREE.Mesh(geometry,material(0x252a31,{roughness:.58}));group.add(body);const face=printedMaterial(),asset=assetFor(game,'cartridgeLabel');getArtworkTexture(asset,()=>titleTexture(game,format),texture=>{face.map=texture;face.needsUpdate=true;});const label=new THREE.Mesh(new THREE.PlaneGeometry(asset.labelRect?h*.87*asset.labelRect[2]/asset.labelRect[3]:w*.72,asset.labelRect?h*.87:h*.55),face);label.position.set(0,0,d/2+.008);group.add(label);group.position.y=h/2;return decorate(group);}
function dispose(root){const geometry=new Set(),materials=new Set();root.traverse(object=>{if(object.geometry)geometry.add(object.geometry);for(const mat of Array.isArray(object.material)?object.material:object.material?[object.material]:[])materials.add(mat);});geometry.forEach(item=>item.dispose());materials.forEach(item=>item.dispose());}
function clear(group){while(group.children.length){const item=group.children.pop();dispose(item);}}
function rows(values){const list=$('#game-details');list.replaceChildren();for(const[label,value]of values){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=label;dd.textContent=value??'—';list.append(dt,dd);}}
function showMedium(game){clear(selectionStage);const format=formats[game.platform],medium=format.medium==='disc'?makeDisc(game,format):makeCartridge(game);medium.position.x=0;medium.position.z=.6;selectionStage.add(medium);}
function selectGame(game,caseRoot){if(selectedCase)selectedCase.position.z=selectedCase.userData.homeZ;selectedCase=caseRoot||null;if(selectedCase)selectedCase.position.z=.26;selectedGame=game;showMedium(game);rows([['Title',game.title],['Platform',currentPlatform.name],['Game ID',game.id||'Not embedded'],['Region',game.region||'Not detected'],['Revision',game.revision??'—'],['Case',formats[game.platform].caseName],['Launch target',game.path]]);const cover=assetFor(game,'frontCover');$('#artwork').textContent=`Cover: ${cover.source} · ${cover.match||'local artwork'}`;$('#source').textContent=game.source;const image=$('#art-preview'),preview=cover.url||game.coverUrl;if(preview){image.src=preview;image.hidden=false;}else{image.removeAttribute('src');image.hidden=true;}artworkControls(game);if($('#auto-artwork').checked && game.artwork && !game.artwork.searchedAt && Object.values(game.artwork.resolved).some(asset=>asset.source==='generated'))findArtwork(game);}
const artworkRequests=new Set();
async function artworkRequest(action,payload){const response=await fetch(`/api/artwork/${action}`,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!response.ok){let message='Restart npm run preview to enable artwork lookup.';try{message=(await response.json()).error||message;}catch{}throw new Error(message);}return response.json();}
function artworkControls(game){const area=$('#artwork-options');area.replaceChildren();$('#find-artwork').disabled=!game.artwork||artworkRequests.has(game.artwork.key);$('#artwork-status').textContent=game.artwork?(artworkRequests.has(game.artwork.key)?'Looking for missing artwork…':game.artwork.errors.join(' · ')):'Restart the preview server to enable artwork lookup.';if(!game.artwork)return;for(const[kind,asset]of Object.entries(game.artwork.resolved)){const section=document.createElement('section');section.className='artwork-option';const title=document.createElement('h3');title.textContent={frontCover:'Box front',discLabel:'Disc label',cartridgeLabel:'Cartridge sticker'}[kind];const status=document.createElement('small');status.textContent=`${asset.source} · ${asset.match}`;const select=document.createElement('select');select.setAttribute('aria-label',title.textContent+' choice');for(const[value,label]of [['automatic','Automatic lookup order'],['generated','Use generated artwork']]){const option=document.createElement('option');option.value=value;option.textContent=label;select.append(option);}const candidates=game.artwork.candidates.filter(c=>c.kind===kind);for(const candidate of candidates){const option=document.createElement('option');option.value=candidate.id;option.textContent=`${candidate.source} · ${candidate.region||'unknown region'} · ${candidate.conflict||candidate.match}${candidate.preparationRequired?' · sticker preparation needed':''}`;option.disabled=!!candidate.preparationRequired;select.append(option);}const preview=document.createElement('img');preview.alt=title.textContent+' candidate preview';preview.hidden=true;const details=document.createElement('small'),source=document.createElement('a');source.target='_blank';source.rel='noopener noreferrer';source.hidden=true;select.addEventListener('change',()=>{const candidate=candidates.find(c=>c.id===select.value);preview.hidden=!candidate;if(candidate){preview.src=candidate.url;details.textContent=candidate.conflict||candidate.label||candidate.match;source.href=candidate.page;source.textContent='View source';source.hidden=false;}else{details.textContent='';source.hidden=true;}});const apply=document.createElement('button');apply.textContent='Use selected artwork';apply.addEventListener('click',async()=>{apply.disabled=true;try{game.artwork=await artworkRequest('select',{gameKey:game.artwork.key,kind,candidateId:select.value});refreshGameArtwork(game);}catch(error){$('#artwork-status').textContent=error.message;}finally{apply.disabled=false;}});section.append(title,status,select,preview,details,source,apply);area.append(section);}}
function refreshGameArtwork(game){if(!currentPlatform.games.includes(game))return;const saved=selectedGame;buildShelf();if(saved && currentPlatform.games.includes(saved)){const root=gallery.children.find(object=>object.userData.game===saved);selectGame(saved,root);}wireframe();}
async function findArtwork(game=selectedGame){if(!game?.artwork||artworkRequests.has(game.artwork.key))return;artworkRequests.add(game.artwork.key);if(selectedGame===game)artworkControls(game);try{game.artwork=await artworkRequest('search',{gameKey:game.artwork.key});refreshGameArtwork(game);}catch(error){game.artwork.searchedAt=new Date().toISOString();game.artwork.errors=[error.message];if(selectedGame===game)artworkControls(game);}finally{artworkRequests.delete(game.artwork.key);if(selectedGame===game)artworkControls(game);}}
$('#find-artwork').addEventListener('click',()=>findArtwork());$('#auto-artwork').addEventListener('change',()=>{if($('#auto-artwork').checked && selectedGame && !selectedGame.artwork?.searchedAt)findArtwork();});
let mediaJobStarted=false;
async function fetchMissingMedia(){
 if(mediaJobStarted)return;mediaJobStarted=true;const button=$('#find-media-artwork');button.disabled=true;
 try{const response=await fetch('/api/artwork/search-missing',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});if(!response.ok)throw new Error('Could not start missing artwork lookup.');const job=await response.json();$('#artwork-status').textContent=job.running?`Fetching missing box and disc artwork (0 of ${job.total || '…'})…`:'Missing box and disc artwork is already up to date.';}catch(error){mediaJobStarted=false;button.disabled=false;$('#artwork-status').textContent=error.message;}
}
$('#find-media-artwork').addEventListener('click',fetchMissingMedia);
function buildShelf(){clear(gallery);clear(selectionStage);pickables=[];selectedCase=null;const games=[...currentPlatform.games].sort((a,b)=>a.title.localeCompare(b.title)),format=formats[currentPlatform.id];if(!games.length){$('#shelf-title').textContent=currentPlatform.name;$('#shelf-count').textContent='NO GAMES DISCOVERED';rows([['Status','No games found']]);$('#artwork').textContent='—';$('#source').textContent='—';return;}const [w,h]=format.caseMm.map(value=>value*MM),columns=Math.min(9,Math.max(4,Math.ceil(Math.sqrt(games.length)))),rowsCount=Math.ceil(games.length/columns),gap=Math.max(.035,w*.11),boardWidth=columns*(w+gap)+.18,boardDepth=.46;for(let row=0;row<rowsCount;row++){const board=new THREE.Mesh(new THREE.BoxGeometry(boardWidth,.08,boardDepth),material(0x5a4437,{roughness:.72}));board.position.set(0,.04+row*(h+.16),-.13);board.receiveShadow=true;gallery.add(board);}games.forEach((game,index)=>{const row=Math.floor(index/columns),col=index%columns,caseRoot=makeCase(game);caseRoot.position.x=(col-(columns-1)/2)*(w+gap);caseRoot.position.y+=.08+row*(h+.16);gallery.add(caseRoot);if(index===0)selectGame(game,caseRoot);});$('#shelf-title').textContent=currentPlatform.name;$('#shelf-count').textContent=`${games.length} LOCAL GAME${games.length===1?'':'S'} · CLICK A CASE`;}
function boxInfo(){const box=new THREE.Box3().setFromObject(gallery);if(!box.isEmpty()){const selectionBox=new THREE.Box3().setFromObject(selectionStage);box.union(selectionBox);}const center=box.getCenter(new THREE.Vector3()),size=box.getSize(new THREE.Vector3());return{center,radius:Math.max(size.length()/2,1.4)};}
function resetView(){const{center,radius}=boxInfo();controls.target.copy(center);camera.position.set(center.x+radius*1.15,Math.max(center.y+radius*.7,2.1),center.z+radius*2.25);controls.update();}
function wireframe(){gallery.traverse(object=>{for(const mat of Array.isArray(object.material)?object.material:object.material?[object.material]:[])mat.wireframe=$('#wireframe').checked;});selectionStage.traverse(object=>{for(const mat of Array.isArray(object.material)?object.material:object.material?[object.material]:[])mat.wireframe=$('#wireframe').checked;});}
async function loadLibrary(force=false){$('#status').textContent='Scanning local files and emulator metadata…';const response=await fetch(`/api/library${force?'?refresh=1':''}`);if(!response.ok)throw new Error(await response.text());library=await response.json();const select=$('#platform');select.replaceChildren();for(const platform of library.platforms){const option=document.createElement('option');option.value=platform.id;option.textContent=`${platform.name} · ${platform.games.length}`;option.disabled=!platform.games.length;select.append(option);}currentPlatform=library.platforms.find(platform=>platform.games.length)||library.platforms[0];select.value=currentPlatform.id;buildShelf();wireframe();resetView();$('#status').textContent=`Ready · ${BUILD} · ${library.platforms.reduce((count,platform)=>count+platform.games.length,0)} games from local libraries`;fetchMissingMedia();}
$('#platform').addEventListener('change',()=>{currentPlatform=library.platforms.find(platform=>platform.id===$('#platform').value);buildShelf();wireframe();resetView();});$('#rescan').addEventListener('click',()=>loadLibrary(true));$('#wireframe').addEventListener('change',wireframe);$('#reset').addEventListener('click',resetView);
for(const button of document.querySelectorAll('[data-view]'))button.addEventListener('click',()=>{const{center,radius}=boxInfo(),distance=Math.max(radius*2.8,3),views={front:[0,0,distance],back:[0,0,-distance],left:[-distance,0,0],right:[distance,0,0],top:[0,distance,.001],perspective:[distance*.75,distance*.55,distance]};camera.position.copy(center).add(new THREE.Vector3(...views[button.dataset.view]));camera.up.set(0,1,0);controls.target.copy(center);controls.update();});
const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();renderer.domElement.addEventListener('pointerdown',event=>{const bounds=renderer.domElement.getBoundingClientRect();pointer.x=(event.clientX-bounds.left)/bounds.width*2-1;pointer.y=-(event.clientY-bounds.top)/bounds.height*2+1;raycaster.setFromCamera(pointer,camera);const hit=raycaster.intersectObjects(pickables,false)[0];if(hit?.object.userData.caseRoot){selectGame(hit.object.userData.caseRoot.userData.game,hit.object.userData.caseRoot);wireframe();}});
let resizeFrame=0;new ResizeObserver(()=>{cancelAnimationFrame(resizeFrame);resizeFrame=requestAnimationFrame(()=>{const{width,height}=$('#viewport').getBoundingClientRect();renderer.setSize(width,height);camera.aspect=width/height;camera.updateProjectionMatrix();});}).observe($('#viewport'));
let last=0;renderer.setAnimationLoop(time=>{const delta=Math.min(last?time-last:0,80);last=time;if($('#rotate').checked)gallery.rotation.y+=delta*.0002;selectionStage.children[0]&&(selectionStage.children[0].rotation[formats[selectedGame?.platform]?.medium==='disc'?'z':'y']+=delta*.00045);controls.update();renderer.render(scene,camera);});
loadLibrary().catch(error=>{$('#status').textContent=`Could not scan library: ${error.message}`;});
